import { Component, inject } from '@angular/core';

// CartStore is declared with @Service(): one instance in the root injector

@Component({
  selector: 'app-cart-badge',
  template: `{{ cart.items().length }}`,
})
export class CartBadge {
  readonly cart = inject(CartStore); // resolved by root
}

@Component({
  selector: 'app-cart-page',
  providers: [CartStore], // a second, private CartStore
  template: `<button (click)="cart.add('Mug')">Add mug</button>`,
})
export class CartPage {
  readonly cart = inject(CartStore); // resolved by CartPage's own injector
}

