import { Component, Service, inject, signal } from '@angular/core';

@Service({ autoProvided: false }) // exists only where it's listed
export class OrderDraft {
  readonly lines = signal<string[]>([]);
}

@Component({
  selector: 'app-order-editor',
  providers: [OrderDraft], // one draft per editor, destroyed with it
  template: `<p>{{ draft.lines().length }} lines</p>`,
})
export class OrderEditor {
  readonly draft = inject(OrderDraft);
}
